/* BERTH.A RC224 — Kids · Raposa de Nuvem · 5 acessórios × 3 cores
   Incremental sobre RC223. Preserva Gato Neblina, Coelho de Nuvem e trilha Kids.
   Assets embutidos para evitar 404/cache. Recorte individual com margem para evitar corte/rebarbas.
*/
(function(){
'use strict';
const BUILD='RC224';
const PALS=['nevoa','coral','misto'];
const PREFIX='bertha.kids.accessory.variant.';
const IDS={
  'mist_mist_v1_fox_head_0':'head',
  'mist_mist_v1_fox_neck_1':'neck',
  'mist_mist_v1_fox_eyes_2':'eyes',
  'mist_mist_v1_fox_back_3':'back',
  'mist_mist_v1_fox_special_4':'special'
};
const NAMES={
  'mist_mist_v1_fox_head_0':'Gorro Aurora',
  'mist_mist_v1_fox_neck_1':'Lenço Estelar',
  'mist_mist_v1_fox_eyes_2':'Óculos da Raposa',
  'mist_mist_v1_fox_back_3':'Mochila Cauda Estelar',
  'mist_mist_v1_fox_special_4':'Amuleto Raposa Celeste'
};
const ASSETS={
    'head-nevoa':'data:image/png;base64,',
    'head-coral':'data:image/png;base64,',
    'head-misto':'data:image/png;base64,',
    'neck-nevoa':'data:image/png;base64,',
    'neck-coral':'data:image/png;base64,',
    'neck-misto':'data:image/png;base64,',
    'eyes-nevoa':'data:image/png;base64,',
    'eyes-coral':'data:image/png;base64,',
    'eyes-misto':'data:image/png;base64,',
    'back-nevoa':'data:image/png;base64,',
    'back-coral':'data:image/png;base64,',
    'back-misto':'data:image/png;base64,',
    'special-nevoa':'data:image/png;base64,',
    'special-coral':'data:image/png;base64,',
    'special-misto':'data:image/png;base64,'
};
const store=()=>window.berthaHmlStorage||window.localStorage;
function selectedKid(){
  const sel=document.querySelector('#r152KidSel');
  if(sel&&sel.value)return String(sel.value);
  if(window.__rc209Member!=null)return String(window.__rc209Member);
  return 'default';
}
function variantFor(aid){
  const n=Number(store().getItem(PREFIX+selectedKid()+'.'+aid));
  return Number.isFinite(n)?Math.max(0,Math.min(2,n)):0;
}
function srcFor(aid){const kind=IDS[aid]; return kind?ASSETS[kind+'-'+PALS[variantFor(aid)]]:'';}
function stamp(){ /* RC227: build badge owned only by final patch */ }
function patch(root=document){
  root.querySelectorAll('.rc209-acc-proxy[data-acc]').forEach(proxy=>{
    const aid=proxy.getAttribute('data-acc'); if(!IDS[aid])return;
    const src=srcFor(aid);
    proxy.classList.add('rc224-fox-asset'); proxy.dataset.rc224='1';
    let im=proxy.querySelector('img');
    if(!im){proxy.replaceChildren(); im=document.createElement('img'); im.alt=''; im.loading='eager'; im.decoding='async'; proxy.appendChild(im);}
    if(im.getAttribute('src')!==src)im.setAttribute('src',src);
    const card=proxy.closest('.r197-acc');
    if(card){const s=card.querySelector('strong'); if(s&&NAMES[aid])s.textContent=NAMES[aid];}
  });
  stamp();
}
const style=document.createElement('style');
style.id='rc224-fox-assets-style';
style.textContent=`
.r197-acc-art .rc224-fox-asset{display:flex!important;align-items:center!important;justify-content:center!important;width:100%!important;height:100%!important;min-height:148px!important;overflow:visible!important;background:transparent!important}
.r197-acc-art .rc224-fox-asset img{display:block!important;width:96%!important;height:142px!important;object-fit:contain!important;object-position:center!important;filter:none!important;transform:none!important}
.r197-acc:has(.rc224-fox-asset) .r197-acc-art{min-height:154px!important;overflow:visible!important}
`;
document.head.appendChild(style);
Object.values(ASSETS).forEach(src=>{const i=new Image();i.decoding='async';i.src=src;});
let raf=0; const schedule=()=>{if(raf)return;raf=requestAnimationFrame(()=>{raf=0;patch(document);});};
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',schedule,{once:true});else schedule();
window.addEventListener('pageshow',schedule);
window.addEventListener('hashchange',()=>setTimeout(schedule,30));
document.addEventListener('click',e=>{if(e.target.closest('[data-r147tab="kids"],[data-rc209variant],#r152KidSel,[data-rc208collection],[data-r152pet]'))setTimeout(schedule,40);},true);
/* RC227: global MutationObserver removed to prevent cross-patch render loop */
})();
